from __future__ import absolute_import
from .radio_base import RadioBase
from hran_radio.radio_connection.frmon_interface import FrmonConnection

from re import match


class Radio5_1Base(RadioBase):
    def __init__(self, radio_ip, sm_ip, msm_ip):
        super(Radio5_1Base, self).__init__(radio_ip, sm_ip, msm_ip)
        self.radio_connection = FrmonConnection(
            self._radio_ip, self._sm_ip, self._msm_ip
        )
        self.release = self.radio_connection.get_smod_release()

    def lte_tx_power(self):
        """
        Return tx power for LTE technology.

        :return: tx power
        :rtype: dict
        """
        tx_power = self.all_tx_power()
        return {tx: power for tx, power in tx_power.items() if match(r"L", tx)}

    def gsm_tx_power(self):
        """
        Return tx power for GSM technology.

        :return: tx power
        :rtype: dict
        """
        tx_power = self.all_tx_power()
        return {tx: power for tx, power in tx_power.items() if match(r"G", tx)}

    def wcdma_tx_power(self):
        """
        Return tx power for WCDMA technology.

        :return: tx power
        :rtype: dict
        """
        tx_power = self.all_tx_power()
        return {tx: power for tx, power in tx_power.items() if match(r"W", tx)}
